import datetime

CL = "client_checklist"
TK = "client_checklist_task"
# Stages a row keeps through a master change: a person decided them, so a sync never overwrites them.
KEEP_STAGES = ("removed", "removal_requested", "retired")


def _s(v):
    return str(v if v is not None else "").strip()


def _link_ids(rec, key):
    out = []
    for v in ((rec or {}).get("links") or {}).get(key) or []:
        if isinstance(v, dict):
            if v.get("id"):
                out.append(str(v["id"]))
        elif v:
            out.append(str(v))
    return out


def _list_all(slug):
    rows, cursor = [], None
    for _ in range(200):
        kw = {"type_slug": slug, "limit": 200}
        if cursor:
            kw["cursor"] = cursor
        res = api.records.list(**kw) or {}
        rows.extend(res.get("records") or [])
        cursor = res.get("nextCursor")
        if not cursor:
            break
    return rows


def _required(step):
    tags = [_s(t).lower() for t in (step.get("tags") or [])]
    text = (_s(step.get("title")) + " " + _s(step.get("description"))).lower()
    return "required" in tags or "[required]" in text


def _steps(tpl):
    body = (tpl or {}).get("body") or {}
    return [s for s in (body.get("steps") or []) if isinstance(s, dict) and _s(s.get("id")) and _s(s.get("title"))]


def _clean_title(title):
    return _s(title).replace("[required]", "").replace("[Required]", "").strip()


now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()
lines = []
client_id = _s(params.get("client_id"))
template_id = _s(params.get("template_id"))
targets = []  # (checklist record, is_new)

if client_id or template_id:
    if not (client_id and template_id):
        raise ValueError("To attach a checklist, choose both a client and a master Activity template.")
    client = api.clients.get(client_id=client_id)
    if not client:
        raise ValueError("That client wasn't found.")
    tpl = api.templates.get(template_id=template_id)
    if not tpl:
        raise ValueError("That Activity template wasn't found, or this automation's owner can't see it.")
    ckey = client_id + ":" + template_id
    existing = [r for r in _list_all(CL) if _s((r.get("data") or {}).get("checklist_key")) == ckey]
    data = {"checklist_key": ckey, "master_template_id": template_id, "master_name": _s(tpl.get("name")), "active": True}
    if _s(params.get("cadence")):
        data["cadence"] = _s(params.get("cadence"))
    if _s(params.get("due_day")):
        data["due_day"] = int(float(_s(params.get("due_day"))))
    if _s(params.get("starts_on")):
        data["starts_on"] = _s(params.get("starts_on"))[:10]
    if _s(params.get("manager_id")):
        data["manager"] = _s(params.get("manager_id"))
    title = _s(client.get("name")) + " · " + _s(tpl.get("name"))
    rec = {"title": title, "data": data, "links": {"client": [client_id]}}
    if _s(params.get("owner_id")):
        rec["ownerUserId"] = _s(params.get("owner_id"))
    if existing:
        cl = api.records.update(type_slug=CL, record_id=existing[0]["id"], record=rec)
        lines.append("Updated " + title + ".")
        targets.append((cl, False))
    else:
        cl = api.records.create(type_slug=CL, record=rec)
        lines.append("Attached " + _s(tpl.get("name")) + " to " + _s(client.get("name")) + ".")
        targets.append((cl, True))
else:
    for r in _list_all(CL):
        if (r.get("data") or {}).get("active") is not False:
            targets.append((r, False))

all_tasks = _list_all(TK) if targets else []
templates = {}

for cl, is_new in targets:
    d = cl.get("data") or {}
    ckey = _s(d.get("checklist_key"))
    tid = _s(d.get("master_template_id"))
    if tid not in templates:
        templates[tid] = api.templates.get(template_id=tid) if tid else None
    tpl = templates[tid]
    if not tpl:
        api.records.update(type_slug=CL, record_id=cl["id"], record={"data": {
            "last_synced": now, "sync_note": "The master Activity template wasn't found, so nothing changed."}})
        lines.append(_s(cl.get("title")) + ": master not found, nothing changed.")
        continue
    client_ids = _link_ids(cl, "client")
    by_step = {}
    for r in all_tasks:
        rd = r.get("data") or {}
        if _s(rd.get("task_key")).startswith(ckey + ":") and _s(rd.get("step_key")):
            by_step[_s(rd.get("step_key"))] = r
    added = held = retired = updated = back = 0
    seen = set()
    for i, st in enumerate(_steps(tpl)):
        sk = _s(st.get("id"))
        seen.add(sk)
        req = _required(st)
        mtitle = _clean_title(st.get("title"))
        row = by_step.get(sk)
        if row is None:
            # A brand-new checklist copies every step. On a later sync, a new required step is added straight
            # away and a new optional step waits for review (decision D7).
            stage = "kept" if (is_new or req) else "new_in_master"
            new = {"title": mtitle, "stage": stage,
                   "data": {"task_key": ckey + ":" + sk, "step_key": sk, "master_title": mtitle,
                            "required_task": req, "position": i},
                   "links": {"checklist": [cl["id"]]}}
            if client_ids:
                new["links"]["client"] = client_ids[:1]
            api.records.create(type_slug=TK, record=new)
            if stage == "kept":
                added += 1
            else:
                held += 1
        else:
            rd = row.get("data") or {}
            patch = {}
            if _s(rd.get("master_title")) != mtitle:
                patch["master_title"] = mtitle
            if bool(rd.get("required_task")) != req:
                patch["required_task"] = req
            if rd.get("position") != i:
                patch["position"] = i
            if patch:
                api.records.update(type_slug=TK, record_id=row["id"], record={"data": patch})
                updated += 1
            if row.get("stage") == "retired":
                api.records.change_stage(type_slug=TK, record_id=row["id"], stage="kept",
                                         note="This step is back in the master Activity template.")
                back += 1
    for sk, row in by_step.items():
        if sk not in seen and row.get("stage") not in KEEP_STAGES:
            api.records.change_stage(type_slug=TK, record_id=row["id"], stage="retired",
                                     note="This step is no longer in the master Activity template.")
            retired += 1
    parts = []
    if is_new:
        parts.append(str(added) + " tasks copied from the master")
    else:
        if added:
            parts.append(str(added) + " new required task(s) added")
        if held:
            parts.append(str(held) + " new optional task(s) waiting for review (New in master)")
        if retired:
            parts.append(str(retired) + " task(s) retired (no longer in the master)")
        if back:
            parts.append(str(back) + " task(s) back in the master")
        if updated:
            parts.append(str(updated) + " task(s) refreshed from the master")
    note = "; ".join(parts) if parts else "Already matches the master."
    api.records.update(type_slug=CL, record_id=cl["id"], record={"data": {
        "last_synced": now, "master_name": _s(tpl.get("name")), "sync_note": note}})
    lines.append(_s(cl.get("title")) + ": " + note + ".")

summary = "\n".join(lines) if lines else "No active client checklists to sync."
checklists_synced = len(targets)
